mapper.select:
select provider_id, model_id, capability, succeeded, probed_at from internal_model_provider_model_probes where model_id in
#{modelId}
order by model_id, capability

mapper.insert:
insert into internal_model_provider_model_probes(
    provider_id, model_id, capability, succeeded, probed_at
) values (
    #{providerId}, #{modelId}, #{capability}, #{succeeded}, #{probedAt}
)
on conflict (provider_id, model_id, capability) do update set
    succeeded = excluded.succeeded,
    probed_at = excluded.probed_at

mapper.update:
merge into internal_model_provider_model_probes target
using (values (
    #{providerId}, #{modelId}, #{capability}, #{succeeded}, #{probedAt}
)) incoming(provider_id, model_id, capability, succeeded, probed_at)
on target.provider_id = incoming.provider_id
   and target.model_id = incoming.model_id
   and target.capability = incoming.capability
when matched then update set
    succeeded = incoming.succeeded,
    probed_at = incoming.probed_at
when not matched then insert (
    provider_id, model_id, capability, succeeded, probed_at
) values (
    incoming.provider_id, incoming.model_id, incoming.capability,
    incoming.succeeded, incoming.probed_at
)
